commands:
node .github/scripts/ci-timing.mjs start lint
trap 'phase_exit=$?; node .github/scripts/ci-timing.mjs finish lint "$phase_exit"; exit "$phase_exit"' EXIT
${{ inputs.lint_command }}

node .github/scripts/ci-timing.mjs start test
trap 'phase_exit=$?; node .github/scripts/ci-timing.mjs finish test "$phase_exit"; exit "$phase_exit"' EXIT
${{ inputs.test_command }}

node .github/scripts/ci-timing.mjs start contracts
trap 'phase_exit=$?; node .github/scripts/ci-timing.mjs finish contracts "$phase_exit"; exit "$phase_exit"' EXIT
${{ inputs.contracts_command }}

with.main_command:
node -e "require('node:fs').mkdirSync('.tmp/ide-dom-headless-preflight', { recursive: true })"
pnpm exec cross-env WEAPP_VITE_E2E_CLEANUP_TRACE=1 pnpm vitest run -c e2e/vitest.e2e.utils.config.ts e2e/utils/devProcessCleanup/windowsKernelQuery.test.ts e2e/utils/devProcessCleanup/processes.test.ts e2e/utils/dev-process.cleanup.test.ts e2e/utils/devProcessCleanup/windowsProcessTree.test.ts e2e/utils/devProcessCleanup/windowsProcessRows.test.ts e2e/utils/devProcessCleanup/windowsQueryTrace.test.ts 2>&1 | tee .tmp/ide-dom-headless-preflight/cleanup.log
pnpm exec cross-env WEAPP_VITE_E2E_CLEANUP_TRACE=1 WEAPP_VITE_E2E_DEV_PROCESS_TRACE=1 WEAPP_VITE_E2E_DEV_SHUTDOWN_TRACE=1 WEAPP_VITE_E2E_DOM_SCOPE_TRACE_CHECKPOINTS=home-ready node --import tsx e2e/scripts/run-e2e-suite.ts ide-dom-headless:classic --plan=.tmp/verification-plan/ide-dom-headless.json --shard-index=${{ matrix.shard }}
